Refactor this function so the two loops share one helper, then write the closing summary for a reviewer who saw none of the work.

def report(rows):
    out = []
    for r in rows:
        if r.kind == 'a':
            out.append(r.total * 1.1)
    for r in rows:
        if r.kind == 'b':
            out.append(r.total * 1.2)
    return out
